pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Owner (this test contract) receives funds; its receive() re-enters C's
    // fallback to deposit. Under the fixed-gas transfer stipend (reference P)
    // the re-entrant deposit always runs out of gas, so withdrawAll reverts
    // and depositsCount stays 1. Under the mutant M, sendMoney forwards all
    // gas via `call`, so the re-entrant deposit succeeds (depositsCount -> 2)
    // and withdrawAll completes.
    receive() external payable {
        (bool s, ) = address(c).call("");
        require(s);
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 100 ether);
        vm.deal(address(c), amount);

        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        assertTrue(!ok && c.depositsCount() == 1);
    }
}

