pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, address(this).balance == 0 ? 1 ether : address(this).balance / 2 + 1);
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint128).max);

        vm.deal(address(this), amount);
        c.fallback{value: amount}();

        uint256 before = address(c).balance;
        assertEq(before, amount);

        // owner of c is the test contract (msg.sender at deployment)
        try c.withdraw(amount) {
            assertTrue(address(c).balance == before - amount, "withdraw must move Ether");
        } catch {
            assertTrue(false, "withdraw by owner should not revert");
        }
    }
}

