pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter r;

    function setUp() public {
        c = new C();
        r = new Reverter();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1 ether);
        vm.deal(address(r), amount);
        vm.prank(address(r));
        (bool sent, ) = address(r).call{value: amount}("");
        require(sent);
        // r (which rejects plain transfers via its reverting fallback) now calls c.withdraw(amount)
        vm.prank(address(r));
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: withdrawing to a receiver that refuses Ether must revert.
        assertTrue(!ok, "withdraw to rejecting receiver must revert");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }

    function attack(C c, uint256 amount) external {
        c.withdraw(amount);
    }
}

