contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // This contract refuses Ether, so any call sending it value fails.
    receive() external payable { revert(); }

    function test(uint amt) public {
        require(amt > 0);
        require(address(this).balance >= amt);

        // Fund c through its payable fallback.
        payable(address(c)).transfer(amt);

        // c tries to send `amt` back to this contract, which rejects it.
        c.sendMoney(address(this), amt);

        // On P the failed call reverts, so this is never violated.
        // On M the failure is silent and c has lost its balance.
        assert(address(c).balance == amt);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function runTest(uint amt) public {
        require(address(this).balance >= amt);
        require(amt > 0);

        // fund the contract via its payable fallback
        (bool dep, ) = address(c).call{value: amt}("");
        require(dep);

        // sendMoney targets this test contract, which has no receive/payable fallback,
        // so the inner call fails. P reverts; M silently continues.
        bool ok;
        (ok, ) = address(c).call(
            abi.encodeWithSelector(c.sendMoney.selector, address(this), amt)
        );

        assert(ok);
    }
}

