contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // Note: this contract intentionally has NO receive/fallback, so it refuses Ether.
    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        require(address(c).balance >= amount);
        // fund c so the failure is due to the target refusing, not c's balance
        (bool funded, ) = address(c).call{value: amount}("");
        require(funded);
        bool reverted;
        try c.sendMoney(address(this), amount) { reverted = false; } catch { reverted = true; }
        // Rule: any sendMoney to a recipient that cannot receive Ether must revert.
        assert(reverted);
    }
}

